FoldedCodePoint searchFold(char32_t codePoint) noexcept
{
    FoldedCodePoint folded;
    if (codePoint < 0x80)
    {
        folded.codePoints[0] = codePoint >= U'A' && codePoint <= U'Z' ? codePoint + (U'a' - U'A') : codePoint;
        folded.count = 1;
        return folded;
    }
    if (codePoint >= 0xC0 && codePoint < 0x180)
    {
        const std::string_view ascii = kLatinFolds[codePoint - 0xC0];
        if (!ascii.empty())
        {
            for (const char c : ascii)
            {
                folded.codePoints[folded.count++] = static_cast<char32_t>(c);
            }
            return folded;
        }
    }
    else if (codePoint >= 0x370 && codePoint < 0x500)
    {
        const char16_t base = kGreekCyrillicFolds[codePoint - 0x370];
        if (base != 0)
        {
            folded.codePoints[0] = base;
            folded.count = 1;
            return folded;
        }
    }
    folded.codePoints[0] = codePoint;
    folded.count = 1;
    return folded;
}

void appendSearchFold(std::string_view text, std::string& out)
{
    usize offset = 0;
    while (offset < text.size())
    {
        const char c = text[offset];
        if (static_cast<u8>(c) < 0x80u)
        {
            out.push_back(c >= 'A' && c <= 'Z' ? static_cast<char>(c - 'A' + 'a') : c);
            ++offset;
            continue;
        }
        const Utf8Decoded decoded = decodeUtf8(text, offset);
        const FoldedCodePoint folded = searchFold(decoded.codePoint);
        for (u32 i = 0; i < folded.count; ++i)
        {
            appendUtf8(out, folded.codePoints[i]);
        }
        offset += decoded.length;
    }
}

std::string searchFold(std::string_view text)
{
    std::string folded;
    folded.reserve(text.size());
    appendSearchFold(text, folded);
    return folded;
}

